new='''export async function revokeSession(sessionId: SessionId): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/**
 * Sign-out: removes the one session the cookie names. An unknown hash matches
 * no row, so revoking twice is harmless.
 */
export async function revokeSessionByTokenHash(
  tokenHash: string,
): Promise<void> {
  getDb().delete(sessions).where(eq(sessions.tokenHash, tokenHash)).run();
}

/** Ends every session of one user — every device — and nobody else's. */
export async function revokeSessionsForUser(userId: UserId): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(eq(sessions.userId, userId))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/**
 * Housekeeping sweep; returns how many rows it removed. Only rows whose own
 * expiry has passed are touched — the same cut-off `findSessionByTokenHash`
 * applies — so live sessions survive the sweep.
 */
export async function purgeExpiredSessions(
  now: IsoTimestamp,
): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lte(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
EOF

