import { defineConfig } from "vitest/config";
export default defineConfig({
  resolve: { alias: { "@": "$P/src" } },
  test: { environment: "node", globals: true, dir: "/tmp/authcheck", include: ["/tmp/authcheck/**/*.test.ts"] },
});
EOF
cat > /tmp/authcheck/auth.test.ts <<EOF
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

const sent: { to: string; token?: string }[] = [];
vi.mock("@/server/services/email-service", () => ({
  renderEmail: async (_t: string, props: Record<string, unknown>) => ({ subject: "s", html: String(props.token ?? ""), text: "" }),
  sendEmail: async (m: { to: string; html: string }) => { sent.push({ to: m.to, token: m.html }); },
}));

import { setupTestDb, resetTestDb } from "$P/tests/helpers/db";
import { resetRateLimits } from "@/lib/rate-limit";
import * as auth from "@/server/services/auth-service";
import { resolveSession, destroySession } from "@/server/services/session-service";
import { getDb } from "@/server/db";

const PW = "Correct-Horse-1";
async function reg(name: string, email: string) {
  return auth.register({ name, email, password: PW, confirmPassword: PW, acceptTerms: true } as never);
}
function lastTokenFor(email: string) { return [...sent].reverse().find((m) => m.to === email && m.token)?.token ?? ""; }

beforeAll(async () => { await setupTestDb(); });
beforeEach(async () => { await resetTestDb(); resetRateLimits(); sent.length = 0; vi.useFakeTimers({ toFake: ["Date"] }); vi.setSystemTime(new Date("2026-03-15T12:00:00Z")); });
afterEach(() => { vi.useRealTimers(); });

describe("auth", () => {
  it("logout ends only that session", async () => {
    await reg("Alice", "alice@example.com"); await reg("Bob", "bob@example.com");
    const a1 = await auth.login({ email: "alice@example.com", password: PW, rememberMe: false });
    const a2 = await auth.login({ email: "alice@example.com", password: PW, rememberMe: false });
    const b1 = await auth.login({ email: "bob@example.com", password: PW, rememberMe: false });
    await destroySession(a1.token);
    expect(await resolveSession(a1.token)).toBeNull();
    expect(await resolveSession(a2.token)).not.toBeNull();
    expect(await resolveSession(b1.token)).not.toBeNull();
    await destroySession(a1.token); await destroySession("nonsense-token-xxxxxxxxxxxxxxxxxxxxxxxx");
    expect(await resolveSession(a2.token)).not.toBeNull();
    const a3 = await auth.login({ email: "alice@example.com", password: PW, rememberMe: false });
    expect(await resolveSession(a3.token)).not.toBeNull();
    expect(a3.token).not.toBe(a1.token);
  });

  it("remember me TTL", async () => {
    await reg("Alice", "alice@example.com");
    const s = await auth.login({ email: "alice@example.com", password: PW, rememberMe: false });
    const r = await auth.login({ email: "alice@example.com", password: PW, rememberMe: true });
    vi.setSystemTime(new Date("2026-03-16T11:59:00Z"));
    expect(await resolveSession(s.token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-03-16T12:00:01Z"));
    expect(await resolveSession(s.token)).toBeNull();
    expect(await resolveSession(r.token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-04-14T11:59:00Z"));
    expect(await resolveSession(r.token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-04-14T12:00:01Z"));
    expect(await resolveSession(r.token)).toBeNull();
  });

  it("reset link lifecycle", async () => {
    await reg("Alice", "alice@example.com"); await reg("Bob", "bob@example.com");
    const laptop = await auth.login({ email: "alice@example.com", password: PW, rememberMe: true });
    const bob = await auth.login({ email: "bob@example.com", password: PW, rememberMe: true });
    await auth.requestPasswordReset({ email: "bob@example.com" });
    const bobTok = lastTokenFor("bob@example.com");
    await auth.requestPasswordReset({ email: "ALICE@Example.com" });
    const t1 = lastTokenFor("alice@example.com");
    await auth.requestPasswordReset({ email: "alice@example.com" });
    const t2 = lastTokenFor("alice@example.com");
    expect(t1).not.toBe(t2);
    await expect(auth.confirmPasswordReset({ token: t1, password: "New-Password-12", confirmPassword: "New-Password-12" })).rejects.toThrow();
    vi.setSystemTime(new Date("2026-03-15T12:59:00Z"));
    await auth.confirmPasswordReset({ token: t2, password: "New-Password-12", confirmPassword: "New-Password-12" });
    await expect(auth.confirmPasswordReset({ token: t2, password: "New-Password-13", confirmPassword: "New-Password-13" })).rejects.toThrow();
    expect(await resolveSession(laptop.token)).toBeNull();
    expect(await resolveSession(bob.token)).not.toBeNull();
    await expect(auth.login({ email: "alice@example.com", password: PW, rememberMe: false })).rejects.toThrow();
    await auth.login({ email: "alice@example.com", password: "New-Password-12", rememberMe: false });
    // bob's link still valid (other account)
    await auth.confirmPasswordReset({ token: bobTok, password: "New-Password-12", confirmPassword: "New-Password-12" });
    // expiry
    await auth.requestPasswordReset({ email: "alice@example.com" });
    const t3 = lastTokenFor("alice@example.com");
    vi.setSystemTime(new Date("2026-03-15T14:00:00Z"));
    await expect(auth.confirmPasswordReset({ token: t3, password: "New-Password-14", confirmPassword: "New-Password-14" })).rejects.toThrow();
    const n = sent.length;
    await auth.requestPasswordReset({ email: "nobody@example.com" });
    expect(sent.length).toBe(n);
  });

  it("rate limits per account", async () => {
    await reg("Alice", "alice@example.com"); await reg("Bob", "bob@example.com");
    let throttled = false;
    for (let i = 0; i < 100 && !throttled; i++) {
      try { await auth.login({ email: i % 2 ? "ALICE@example.com" : "alice@example.com", password: "wrong", rememberMe: false }); }
      catch (e) { if (/too many/i.test(String(e))) throttled = true; }
    }
    expect(throttled).toBe(true);
    await expect(auth.login({ email: "alice@example.com", password: PW, rememberMe: false })).rejects.toThrow(/too many/i);
    await auth.login({ email: "bob@example.com", password: PW, rememberMe: false });
    await auth.requestPasswordReset({ email: "alice@example.com" });
    const t = lastTokenFor("alice@example.com");
    await auth.confirmPasswordReset({ token: t, password: "New-Password-12", confirmPassword: "New-Password-12" });
    for (let i = 0; i < 20; i++) await auth.requestPasswordReset({ email: "alice@example.com" });
    const n = sent.length;
    await auth.requestPasswordReset({ email: "alice@example.com" });
    expect(sent.length).toBe(n);
    await auth.requestPasswordReset({ email: "bob@example.com" });
    expect(sent.length).toBe(n + 1);
    await auth.confirmPasswordReset({ token: lastTokenFor("bob@example.com"), password: "New-Password-12", confirmPassword: "New-Password-12" });
    vi.setSystemTime(new Date("2026-03-15T13:00:00Z"));
    await auth.login({ email: "alice@example.com", password: "New-Password-12", rememberMe: false });
  });
});
EOF
